def valid_row(row):
    if not isinstance(row, dict):
        raise ValueError('row must be an object')
    value = row.get('lesson_id')
    if not isinstance(value, str) or not value.strip():
        raise ValueError('lesson_id must be a non-empty string')
    return value.strip()

assert valid_row({'lesson_id': ' loops '}) == 'loops'
for bad in [None, {'lesson_id': 3}, {'lesson_id': '  '}]:
    try:
        valid_row(bad)
    except ValueError:
        pass
    else:
        raise AssertionError('invalid row should fail')
